const visual = {
  prepare: function (input) { return []; },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var margin = 24;
    var side = Math.min(W, H) - margin * 2;
    if (!(side > 0)) { side = Math.max(Math.min(W, H) * 0.8, 1); }
    var x0 = (W - side) / 2;
    var y0 = (H - side) / 2;
    var step = side / 4;
    var paths = [];
    var children = [];
    var i;
    var x, y;
    for (i = 0; i <= 4; i++) {
      x = x0 + step * i;
      paths.push({ id: 'v' + i, commands: [['M', x, y0], ['L', x, y0 + side]] });
      y = y0 + step * i;
      paths.push({ id: 'h' + i, commands: [['M', x0, y], ['L', x0 + side, y]] });
    }
    for (i = 0; i < paths.length; i++) {
      children.push({ type: 'path', pathId: paths[i].id, fill: '#26354a', stroke: { width: 2 } });
    }
    return {
      schemaVersion: 1,
      sceneId: 'grid4x4',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
